import math

def is_square(n):
    if n < 0:
        return False
    sqrt_n = math.isqrt(n)
    return sqrt_n * sqrt_n == n

solutions = []
for a in range(30):
    for b in range(30):
        val = 2**a * 5**b + 625
        if is_square(val):
            N = math.isqrt(val)
            solutions.append((a, b, N))
            solutions.append((a, b, -N))

print(f"{solutions=}")

